use settled_core::ITEMS_DIR_NAME;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

/// Paths generated by `settled new <item-id>`.
#[derive(Debug, Clone)]
pub struct CreatedItemPaths {
    pub item_id: String,
    pub item_dir: PathBuf,
    pub meta_path: PathBuf,
    pub readme_path: PathBuf,
}

/// Validates `<item-id>` format for cross-platform safety and `load_workspace` visibility.
pub fn validate_new_item_id(id: &str) -> Result<(), String> {
    if id.is_empty() {
        return Err("Item ID cannot be empty".to_string());
    }
    if id.len() > 128 {
        return Err("Item ID must be 128 characters or fewer".to_string());
    }
    if id.starts_with('.') || id.starts_with('-') || id.starts_with('_') {
        return Err(format!(
            "Invalid item ID '{id}': must start with an ASCII lowercase letter or digit"
        ));
    }
    if !id
        .chars()
        .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-' || c == '_')
    {
        return Err(format!(
            "Invalid item ID '{id}': only lowercase ASCII letters, digits, '-', and '_' are allowed (e.g. 'git-config')"
        ));
    }
    Ok(())
}

/// Creates `<workspace>/settled-items/<item-id>/` containing a starter `meta.json` and an empty `README.md`.
pub fn create_item_scaffold(workspace_root: &Path, item_id: &str) -> Result<CreatedItemPaths, String> {
    validate_new_item_id(item_id)?;

    let items_dir = workspace_root.join(ITEMS_DIR_NAME);
    let item_dir = items_dir.join(item_id);
    if item_dir.exists() {
        return Err(format!(
            "Item '{item_id}' already exists at {}",
            item_dir.display()
        ));
    }

    fs::create_dir_all(&item_dir).map_err(|e| {
        format!(
            "Failed to create item directory '{}': {e}",
            item_dir.display()
        )
    })?;

    let display_name = humanize_item_id(item_id);
    let now_secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64;

    let meta_json = serde_json::json!({
        "name": display_name,
        "description": "",
        "createAt": now_secs,
        "scripts": {
            "check": [
                "echo \"TODO: implement check\" && exit 1"
            ]
        }
    });

    let meta_content = serde_json::to_string_pretty(&meta_json)
        .map_err(|e| format!("Failed to serialize starter meta.json: {e}"))?;
    let meta_path = item_dir.join("meta.json");
    let readme_path = item_dir.join("README.md");

    fs::write(&meta_path, format!("{meta_content}\n"))
        .map_err(|e| format!("Failed to write '{}': {e}", meta_path.display()))?;
    fs::write(&readme_path, "")
        .map_err(|e| format!("Failed to write '{}': {e}", readme_path.display()))?;

    Ok(CreatedItemPaths {
        item_id: item_id.to_string(),
        item_dir,
        meta_path,
        readme_path,
    })
}

fn humanize_item_id(id: &str) -> String {
    id.split(['-', '_'])
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            match chars.next() {
                Some(first) => {
                    let mut word = first.to_uppercase().collect::<String>();
                    word.push_str(chars.as_str());
                    word
                }
                None => String::new(),
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}
